package com.cohenadair.anglerslog.locations;

import android.graphics.Color;
import android.os.Bundle;
import android.view.LayoutInflater;
import android.view.MotionEvent;
import android.view.View;
import android.view.ViewGroup;
import android.widget.ImageButton;
import android.widget.ImageView;
import android.widget.LinearLayout;

import com.cohenadair.anglerslog.R;
import com.cohenadair.anglerslog.activities.LayoutSpecActivity;
import com.cohenadair.anglerslog.fragments.DraggableMapFragment;
import com.cohenadair.anglerslog.fragments.ManageContentFragment;
import com.cohenadair.anglerslog.model.user_defines.FishingSpot;
import com.cohenadair.anglerslog.model.user_defines.UserDefineObject;
import com.cohenadair.anglerslog.utilities.AlertUtils;
import com.cohenadair.anglerslog.utilities.GoogleMapLayout;
import com.cohenadair.anglerslog.utilities.Utils;
import com.cohenadair.anglerslog.views.InputTextView;
import com.google.android.gms.maps.GoogleMap;
import com.google.android.gms.maps.model.LatLng;

import java.util.List;

/**
 * The ManageFishingSpotFragment is used to add and edit fishing spots. This
 * {@link ManageContentFragment} subclass works slightly different than others. It doesn't interact
 * with the backend database directly. This is so {@link FishingSpot} objects aren't manipulated in
 * the database before the user saves the location.
 *
 * @author Cohen Adair
 */
public class ManageFishingSpotFragment extends ManageContentFragment {

    private InputTextView mNameView;
    private InputTextView mLatitudeView;
    private InputTextView mLongitudeView;
    private DraggableMapFragment mMapFragment;
    private ImageView mCrosshairs;
    private GoogleMap mMap;

    private List<UserDefineObject> mFishingSpots;
    private ManageObjectSpec mManageObjectSpec;
    private InitializeInterface mInitializeInterface;
    private OnVerifyInterface mOnVerifyInterface;

    // if we're adding a fishing spot to a location that already has spots, we want to zoom to the
    // other spots for user convenience
    private boolean mStopLocationUpdates;

    /**
     * Used to verify the new fishing spot being added is unique to the location.
     */
    public interface OnVerifyInterface {
        boolean isDuplicate(FishingSpot fishingSpot);
    }

    public ManageFishingSpotFragment() {
        // Required empty public constructor
    }

    public FishingSpot getNewFishingSpot() {
        return (FishingSpot)getNewObject();
    }

    @Override
    public View onCreateView(LayoutInflater inflater, ViewGroup container, Bundle savedInstanceState) {
        View view = inflater.inflate(R.layout.fragment_manage_fishing_spot, container, false);

        mCrosshairs = (ImageView)view.findViewById(R.id.crosshairs);

        initNameView(view);
        initCoordinatesView(view);
        initMapFragment();
        initRefreshButton(view);
        initSubclassObject();
        initToolbar();

        return view;
    }

    @Override
    public void onResume() {
        super.onResume();
    }

    @Override
    public ManageObjectSpec getManageObjectSpec() {
        return mManageObjectSpec;
    }

    @Override
    public void onDismiss() {
        LayoutSpecActivity activity = (LayoutSpecActivity)getActivity();
        activity.setActionBarTitle(activity.getViewTitle());
    }

    public void setFishingSpots(List<UserDefineObject> fishingSpots) {
        mFishingSpots = fishingSpots;
    }

    public void setManageObjectSpec(ManageObjectSpec manageObjectSpec) {
        mManageObjectSpec = manageObjectSpec;
    }

    public void setInitializeInterface(InitializeInterface initializeInterface) {
        mInitializeInterface = initializeInterface;
    }

    public void setOnVerifyInterface(OnVerifyInterface onVerifyInterface) {
        mOnVerifyInterface = onVerifyInterface;
    }

    @Override
    public void initSubclassObject() {
        initObject(mInitializeInterface);
    }

    @Override
    public boolean verifyUserInput() {
        FishingSpot fishingSpot = getNewFishingSpot();
        fishingSpot.setName(mNameView.getInputText());

        if (mMap != null) {
            fishingSpot.setLatitude(mMap.getCameraPosition().target.latitude);
            fishingSpot.setLongitude(mMap.getCameraPosition().target.longitude);
        } else {
            // in case Google Play Services isn't available, fishing spots can still be added and updated later
            fishingSpot.setLatitude(0.0);
            fishingSpot.setLongitude(0.0);
        }

        // name
        if (fishingSpot.isNameNull()) {
            AlertUtils.showError(getActivity(), R.string.error_name);
            return false;
        }

        // duplicate name
        if (!isEditing() && mOnVerifyInterface.isDuplicate(fishingSpot)) {
            AlertUtils.showError(getActivity(), R.string.error_fishing_spot_name);
            return false;
        }

        return true;
    }

    @Override
    public void updateViews() {
        mNameView.setInputText(getNewFishingSpot().getName() != null ? getNewFishingSpot().getName() : "");
        updateMap();
    }

    private void updateMap() {
        if (mMap == null)
            return;

        updateCrosshairs(mMap.getMapType());

        // move the camera to the current fishing spot
        if (isEditing()) {
            mStopLocationUpdates = true;
            updateCamera(getNewFishingSpot().getCoordinates());
        } else if (mFishingSpots != null) {
            // if the location already has fishing spots, move the camera to one
            // this is simply for user convenience
            if (mFishingSpots.size() > 0) {
                mStopLocationUpdates = true;
                updateCamera(((FishingSpot)mFishingSpots.get(0)).getCoordinates());
            }
        }
    }

    /**
     * Adds an icon to the toolbar that allows users to change the map type.
     */
    private void initToolbar() {
        // find the toolbar layout
        LinearLayout toolbar = null;

        View parent = getParentFragment().getView();
        if (parent != null)
            toolbar = (LinearLayout)parent.findViewById(R.id.toolbar_view);

        // create the icon
        ImageButton mapType = new ImageButton(getContext());

        mapType.setImageResource(R.drawable.ic_map);
        mapType.setBackgroundResource(Utils.resIdFromAttr(getContext(), android.R.attr.selectableItemBackground));
        mapType.setContentDescription(getResources().getString(R.string.select_map_type));
        mapType.setColorFilter(Color.BLACK);
        mapType.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                mMapFragment.onClickMapTypeOption(true);
            }
        });

        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(
                getResources().getDimensionPixelOffset(R.dimen.image_button_size),
                getResources().getDimensionPixelOffset(R.dimen.image_button_size)
        );

        params.setMargins(
                0,
                getResources().getDimensionPixelOffset(R.dimen.margin_default),
                getResources().getDimensionPixelOffset(R.dimen.margin_default),
                getResources().getDimensionPixelOffset(R.dimen.margin_default)
        );

        mapType.setLayoutParams(params);

        // add the icon
        if (toolbar != null)
            toolbar.addView(mapType);
    }

    private void initNameView(View view) {
        mNameView = (InputTextView)view.findViewById(R.id.name_view);
    }

    private void initCoordinatesView(View view) {
        mLatitudeView = (InputTextView)view.findViewById(R.id.latitude_layout);
        mLatitudeView.setAllowsNegativeNumbers(true);

        mLongitudeView = (InputTextView)view.findViewById(R.id.longitude_layout);
        mLongitudeView.setAllowsNegativeNumbers(true);
    }

    private void initRefreshButton(View view) {
        ImageButton refreshButton = (ImageButton)view.findViewById(R.id.coordinate_refresh_button);
        refreshButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                if (mLatitudeView.getInputText() == null || mLongitudeView.getInputText() == null)
                    return;

                double lat = validateCoordinateInput(mLatitudeView);
                double lng = validateCoordinateInput(mLongitudeView);

                if (lat != -1 && lng != -1) {
                    LatLng latLng = new LatLng(lat, lng);

                    if (mMapFragment.isValid(latLng)) {
                        mMapFragment.updateCameraNoZoom(latLng);
                    }
                }
            }
        });
    }

    private void updateCoordinateViews(LatLng coordinates) {
        mLatitudeView.setInputText(String.format(getResources().getConfiguration().locale, "%.6f", coordinates.latitude));
        mLongitudeView.setInputText(String.format(getResources().getConfiguration().locale, "%.6f", coordinates.longitude));
    }

    /**
     * Validates the given {@link InputTextView}. If the input is invalid a Toast will be displayed
     * to the user and the previously entered character will be removed.
     *
     * @param input The {@link InputTextView} to validate.
     * @return The text of the input as a double.
     */
    private double validateCoordinateInput(InputTextView input) {
        String inputText = input.getInputText();

        // do not validate if the user is entering a negative coordinate
        if (inputText.length() == 1 && inputText.charAt(0) == '-')
            return -1;

        try {
            inputText = inputText.replace(',', '.'); // some countries/keyboard use ',' in place of '.'
            return (double) Utils.asFloat(inputText, 0);
        } catch (NumberFormatException e) {
            e.printStackTrace();
            Utils.showToast(getContext(), R.string.msg_invalid_coordinate);
            input.pressBackspace();
        }

        return -1;
    }

    private void initMapFragment() {
        mMapFragment = (DraggableMapFragment)getChildFragmentManager().findFragmentById(R.id.fishing_spot_map);

        mMapFragment.setLocationEnabled(true);
        mMapFragment.setLocationUpdatesEnabled(true);
        mMapFragment.setHasOptionsMenu(false);

        mMapFragment.getMapAsync(new DraggableMapFragment.InteractionListener() {
            @Override
            public void onMapReady(GoogleMap map) {
                mMap = map;
                updateMap();
            }

            @Override
            public void onLocationUpdate(android.location.Location location) {
                if (mStopLocationUpdates) {
                    mMapFragment.setLocationUpdatesEnabled(false);
                    return;
                }

                updateCamera(new LatLng(location.getLatitude(), location.getLongitude()));
                mMapFragment.setLocationUpdatesEnabled(false);
            }
        });

        mMapFragment.setOnDragListener(new GoogleMapLayout.OnDragListener() {
            @Override
            public void onDrag(MotionEvent motionEvent) {
                if (mMap != null)
                    updateCoordinateViews(mMap.getCameraPosition().target);
            }
        });

        mMapFragment.setOnUpdateMapType(new DraggableMapFragment.OnUpdateMapType() {
            @Override
            public void onUpdate(int mapType) {
                updateCrosshairs(mapType);
            }
        });

        updateCoordinateViews(new LatLng(0.0, 0.0));
    }

    private void updateCamera(LatLng loc) {
        mMapFragment.updateCamera(loc);
        updateCoordinateViews(loc);
    }

    /**
     * Changes the color of the center crosshairs depending on the given map type.
     * @param mapType The type of the map.
     */
    private void updateCrosshairs(int mapType) {
        boolean isDark = mapType == GoogleMap.MAP_TYPE_SATELLITE || mapType == GoogleMap.MAP_TYPE_HYBRID;
        mCrosshairs.setColorFilter(isDark ? Color.WHITE : Color.BLACK);
    }
}

package com.cohenadair.anglerslog.locations;

import android.os.Bundle;
import android.support.annotation.Nullable;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.LinearLayout;

import com.cohenadair.anglerslog.R;
import com.cohenadair.anglerslog.fragments.ManageContentFragment;
import com.cohenadair.anglerslog.fragments.ManageFragment;
import com.cohenadair.anglerslog.model.Logbook;
import com.cohenadair.anglerslog.model.user_defines.FishingSpot;
import com.cohenadair.anglerslog.model.user_defines.Location;
import com.cohenadair.anglerslog.model.user_defines.UserDefineObject;
import com.cohenadair.anglerslog.utilities.AlertUtils;
import com.cohenadair.anglerslog.utilities.ViewUtils;
import com.cohenadair.anglerslog.views.InputButtonView;
import com.cohenadair.anglerslog.views.InputTextView;
import com.cohenadair.anglerslog.views.MoreDetailView;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

/**
 * The ManageLocationFragment is used to add and edit locations.
 */
public class ManageLocationFragment extends ManageContentFragment {

    private LinearLayout mContainer;
    private InputTextView mNameView;

    private ArrayList<MoreDetailView> mFishingSpotViews;
    private ArrayList<UserDefineObject> mFishingSpots;

    public ManageLocationFragment() {
        // Required empty public constructor
    }

    private Location getNewLocation() {
        return (Location)getNewObject();
    }

    @Override
    public View onCreateView(LayoutInflater inflater, ViewGroup container, Bundle savedInstanceState) {
        View view = inflater.inflate(R.layout.fragment_manage_location, container, false);

        mContainer = (LinearLayout)view.findViewById(R.id.container);

        initNameView(view);
        initAddFishingSpotView(view);
        initSubclassObject();

        if (mFishingSpots == null || !isEditing())
            mFishingSpots = new ArrayList<>();

        if (mFishingSpotViews == null)
            mFishingSpotViews = new ArrayList<>();

        return view;
    }

    @Override
    public void onResume() {
        super.onResume();
        mNameView.addOnInputTextChangedListener(ViewUtils.onTextChangedListener(new ViewUtils.OnTextChangedListener() {
            @Override
            public void onTextChanged(String newText) {
                getNewLocation().setName(newText);
            }
        }));
    }

    @Override
    public ManageObjectSpec getManageObjectSpec() {
        return new ManageObjectSpec(R.string.error_location_add, R.string.success_location_add, R.string.error_location_edit, R.string.success_location_edit, new ManageInterface() {
            @Override
            public boolean onEdit() {
                if (Logbook.editLocation(getEditingId(), getNewLocation())) {
                    getNewLocation().setFishingSpots(mFishingSpots);
                    return true;
                }

                return false;
            }

            @Override
            public boolean onAdd() {
                if (Logbook.addLocation(getNewLocation())) {
                    getNewLocation().setFishingSpots(mFishingSpots);
                    return true;
                }

                return false;
            }
        });
    }

    @Override
    public void initSubclassObject() {
        initObject(new InitializeInterface() {
            @Override
            public UserDefineObject onGetOldObject() {
                return Logbook.getLocation(getEditingId());
            }

            @Override
            public UserDefineObject onGetNewEditObject(UserDefineObject oldObject) {
                Location loc = new Location((Location)oldObject, true);
                mFishingSpots = loc.getFishingSpots();
                return loc;
            }

            @Override
            public UserDefineObject onGetNewBlankObject() {
                return new Location();
            }
        });
    }

    @Override
    public boolean verifyUserInput() {
        Location loc = getNewLocation();

        // name
        if (loc.isNameNull()) {
            AlertUtils.showError(getActivity(), R.string.error_name);
            return false;
        }

        // duplicate name
        if (isNameDifferent() && Logbook.locationExists(loc)) {
            AlertUtils.showError(getActivity(), R.string.error_location_name);
            return false;
        }

        // fishing spots
        if (mFishingSpots.size() <= 0) {
            AlertUtils.showError(getActivity(), R.string.error_no_fishing_spots);
            return false;
        }

        return true;
    }

    @Override
    public void updateViews() {
        mNameView.setInputText(getNewLocation().getName() != null ? getNewLocation().getName() : "");
        updateAllFishingSpots();
    }

    private void updateAllFishingSpots() {
        // remove all old views
        for (MoreDetailView fishingSpotView : mFishingSpotViews) {
            ViewGroup parent = ((ViewGroup)fishingSpotView.getParent());
            if (parent != null)
                parent.removeView(fishingSpotView);
        }

        for (UserDefineObject spot : mFishingSpots)
            addFishingSpot((FishingSpot)spot);
    }

    private void initNameView(View view) {
        mNameView = (InputTextView)view.findViewById(R.id.name_view);
    }

    private void initAddFishingSpotView(View view) {
        InputButtonView addFishingSpotView = (InputButtonView)view.findViewById(R.id.add_fishing_spot_view);
        addFishingSpotView.setOnClickPrimaryButton(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                goToManageFishingSpot(null);
            }
        });
    }

    private void addFishingSpot(final FishingSpot spot) {
        final MoreDetailView fishingSpotView = new MoreDetailView(getContext());
        fishingSpotView.setTitle(spot.getName());
        fishingSpotView.setSubtitle(spot.getCoordinatesAsString());
        fishingSpotView.setDetailButtonImage(R.drawable.ic_remove);
        fishingSpotView.setTitleStyle(R.style.TextView_Small);
        fishingSpotView.setSubtitleStyle(R.style.TextView_SmallSubtitle);
        fishingSpotView.useNoLeftSpacing();
        fishingSpotView.useDefaultStyle();

        fishingSpotView.setOnClickDetailButton(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                mFishingSpots.remove(spot);
                mContainer.removeView(fishingSpotView);
            }
        });

        fishingSpotView.setOnClickContent(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                goToManageFishingSpot(spot.getId());
            }
        });

        mFishingSpotViews.add(fishingSpotView);
        mContainer.addView(fishingSpotView);
    }

    /**
     * Opens a ManageFishingSpotFragment dialog.
     * @param editingId The editing id of the fishing spot, or null if a new spot is being added.
     */
    private void goToManageFishingSpot(UUID editingId) {
        final ManageFishingSpotFragment fragment = new ManageFishingSpotFragment();

        if (editingId != null)
            fragment.setIsEditing(true, editingId);

        // get all possible fishing spots to be used when adding a new spot
        // this is purely for user convenience
        List<UserDefineObject> allPossibleFishingSpots = mFishingSpots;
        mFishingSpots.addAll(getNewLocation().getFishingSpots());
        fragment.setFishingSpots(allPossibleFishingSpots);

        fragment.setOnVerifyInterface(new ManageFishingSpotFragment.OnVerifyInterface() {
            @Override
            public boolean isDuplicate(FishingSpot fishingSpot) {
                for (UserDefineObject obj : mFishingSpots)
                    if (obj.getName().equals(fishingSpot.getName()))
                        return true;

                return false;
            }
        });

        fragment.setManageObjectSpec(new ManageObjectSpec(R.string.error_fishing_spot_add, R.string.success_fishing_spot_add, R.string.error_fishing_spot_edit, R.string.success_fishing_spot_edit, new ManageInterface() {
            @Override
            public boolean onEdit() {
                for (int i = 0; i < mFishingSpots.size(); i++)
                    // update the fishing spot if this is the one we're editing
                    if (mFishingSpots.get(i).getId().equals(fragment.getNewFishingSpot().getId())) {
                        mFishingSpots.set(i, new FishingSpot(fragment.getNewFishingSpot(), true));
                        updateViews();
                        return true;
                    }

                return false;
            }

            @Override
            public boolean onAdd() {
                mFishingSpots.add(fragment.getNewFishingSpot());
                addFishingSpot(fragment.getNewFishingSpot());
                return true;
            }
        }));

        fragment.setInitializeInterface(new InitializeInterface() {
            @Override
            public UserDefineObject onGetOldObject() {
                return getFishingSpot(fragment.getEditingId());
            }

            @Override
            public UserDefineObject onGetNewEditObject(UserDefineObject oldObject) {
                return new FishingSpot((FishingSpot) oldObject, true);
            }

            @Override
            public UserDefineObject onGetNewBlankObject() {
                return new FishingSpot();
            }
        });

        ManageFragment manageFragment = new ManageFragment();
        manageFragment.setTitle(R.string.empty);
        manageFragment.setContentFragment(fragment);
        manageFragment.show(getChildFragmentManager(), null);
    }

    @Nullable
    private FishingSpot getFishingSpot(UUID id) {
        for (UserDefineObject fishingSpot : mFishingSpots)
            if (fishingSpot.getId().equals(id))
                return (FishingSpot)fishingSpot;

        return null;
    }

}

package com.cohenadair.anglerslog.model.user_defines;

import android.content.ContentValues;
import android.content.Context;

import com.cohenadair.anglerslog.database.QueryHelper;
import com.cohenadair.anglerslog.database.cursors.CatchCursor;
import com.cohenadair.anglerslog.database.cursors.UserDefineCursor;
import com.cohenadair.anglerslog.model.Logbook;
import com.cohenadair.anglerslog.model.backup.Json;
import com.google.android.gms.maps.model.LatLng;

import org.json.JSONException;
import org.json.JSONObject;

import java.util.ArrayList;
import java.util.UUID;

import static com.cohenadair.anglerslog.database.LogbookSchema.CatchTable;
import static com.cohenadair.anglerslog.database.LogbookSchema.FishingSpotTable;

/**
 * The FishingSpot object stores information on a single fishing spot (not an entire location);
 * @author Cohen Adair
 */
public class FishingSpot extends UserDefineObject {

    private double mLatitude = 0.0;
    private double mLongitude = 0.0;
    private UUID mLocationId;

    public FishingSpot() {
        this("");
    }

    public FishingSpot(String name) {
        super(name);
    }

    public FishingSpot(FishingSpot fishingSpot, boolean keepId) {
        super(fishingSpot, keepId);
        mLatitude = fishingSpot.getLatitude();
        mLongitude = fishingSpot.getLongitude();
        mLocationId = fishingSpot.getLocationId();
    }

    public FishingSpot(UserDefineObject obj) {
        super(obj);
    }

    public FishingSpot(UserDefineObject obj, boolean keepId) {
        super(obj, keepId);
    }

    public FishingSpot(JSONObject jsonObject) throws JSONException {
        super(jsonObject);

        // read in coordinates
        JSONObject coordinatesJson = jsonObject.getJSONObject(Json.COORDINATES);
        mLatitude = Double.parseDouble(coordinatesJson.getString(Json.LATITUDE));
        mLongitude = Double.parseDouble(coordinatesJson.getString(Json.LONGITUDE));
    }

    //region Getters & Setters
    public double getLatitude() {
        return mLatitude;
    }

    public void setLatitude(double latitude) {
        mLatitude = latitude;
    }

    public double getLongitude() {
        return mLongitude;
    }

    public void setLongitude(double longitude) {
        mLongitude = longitude;
    }

    public UUID getLocationId() {
        return mLocationId;
    }

    public void setLocationId(UUID locationId) {
        mLocationId = locationId;
    }
    //endregion

    public LatLng getCoordinates() {
        return new LatLng(mLatitude, mLongitude);
    }

    public Location getLocation() {
        return Logbook.getLocation(mLocationId);
    }

    public String getLocationName() {
        return getLocation().getName();
    }

    @Override
    public String getDisplayName() {
        return getLocationName() + " - " + getName();
    }

    /**
     * Gets a string representation of the FishingSpot's coordinates. The result of this method
     * includes "Latitude" and "Longitude" labels.
     *
     * @param lat "Latitude" string.
     * @param lng "Longitude" string.
     * @return A String of the FishingSpot's coordinates.
     */
    public String getCoordinatesAsString(String lat, String lng) {
        return String.format(lat + ": %.6f, " + lng + ": %.6f", mLatitude, mLongitude);
    }

    /**
     * Gets a string representation of the FishingSpot's coordinates. The result of this method
     * <b>does not</b> include "Latitude" and "Longitude" labels.
     * @see #getCoordinatesAsString(String, String)
     */
    public String getCoordinatesAsString() {
        return String.format("%.6f, %.6f", mLatitude, mLongitude);
    }

    /**
     * @return An {@link ArrayList} of {@link Catch} objects associated with this
     * {@link FishingSpot}.
     */
    public ArrayList<UserDefineObject> getCatches() {
        return QueryHelper.queryUserDefines(QueryHelper.queryCatches(CatchTable.Columns.FISHING_SPOT_ID + " = ?", new String[] { getIdAsString() }), new QueryHelper.UserDefineQueryInterface() {
            @Override
            public UserDefineObject getObject(UserDefineCursor cursor) {
                return new CatchCursor(cursor).getCatch();
            }
        });
    }

    public int getNumberOfCatches() {
        return QueryHelper.queryFishingSpotCatchCount(this);
    }

    public ContentValues getContentValues(UUID locationId) {
        ContentValues values = super.getContentValues();

        values.put(FishingSpotTable.Columns.LOCATION_ID, locationId.toString());
        values.put(FishingSpotTable.Columns.LATITUDE, mLatitude);
        values.put(FishingSpotTable.Columns.LONGITUDE, mLongitude);

        return values;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public JSONObject toJson() throws JSONException {
        JSONObject json = super.toJson();

        JSONObject coordinates = new JSONObject();
        coordinates.put(Json.LATITUDE, mLatitude);
        coordinates.put(Json.LONGITUDE, mLongitude);
        json.put(Json.COORDINATES, coordinates);

        // for iOS Core Data compatibility
        json.put(Json.LOCATION, getLocationName());

        return json;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public String toKeywordsString(Context context) {
        StringBuilder builder = new StringBuilder(super.toKeywordsString(context));

        appendToBuilder(builder, (float)mLatitude);
        appendToBuilder(builder, (float)mLongitude);
        appendToBuilder(builder, getLocationName());

        return builder.toString();
    }
}

package com.cohenadair.anglerslog.model.user_defines;

import android.content.Context;
import android.content.Intent;

import com.cohenadair.anglerslog.database.QueryHelper;
import com.cohenadair.anglerslog.database.cursors.FishingSpotCursor;
import com.cohenadair.anglerslog.database.cursors.UserDefineCursor;
import com.cohenadair.anglerslog.model.Logbook;
import com.cohenadair.anglerslog.model.backup.Json;
import com.cohenadair.anglerslog.model.backup.JsonExporter;
import com.cohenadair.anglerslog.model.utilities.HasCatchesInterface;
import com.cohenadair.anglerslog.model.utilities.UserDefineArrays;

import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;

import java.util.ArrayList;
import java.util.UUID;

import static com.cohenadair.anglerslog.database.LogbookSchema.FishingSpotTable;

/**
 * The Location object stores information on a single location, including many fishing spots
 * within that location.
 *
 * @author Cohen Adair
 */
public class Location extends UserDefineObject implements HasCatchesInterface {

    public Location() {
        this("");
    }

    public Location(String name) {
        super(name);
    }

    public Location(Location location, boolean keepId) {
        super(location, keepId);
    }

    public Location(UserDefineObject obj) {
        super(obj);
    }

    public Location(UserDefineObject obj, boolean keepId) {
        super(obj, keepId);
    }

    public Location(JSONObject jsonObject) throws JSONException {
        super(jsonObject);

        JSONArray fishingSpotsJson = jsonObject.getJSONArray(Json.FISHING_SPOTS);
        ArrayList<UserDefineObject> fishingSpots = new ArrayList<>();

        for (int i = 0; i < fishingSpotsJson.length(); i++)
            fishingSpots.add(new FishingSpot(fishingSpotsJson.getJSONObject(i)));

        setFishingSpots(fishingSpots);
    }

    //region Getters & Setters
    @Override
    public void setIsSelected(boolean isSelected) {
        super.setIsSelected(isSelected);
        Logbook.editLocation(getId(), this);
    }
    //endregion

    //region Fishing Spot Manipulation
    public ArrayList<UserDefineObject> getFishingSpots() {
        return QueryHelper.queryUserDefines(
                QueryHelper.queryUserDefines(
                        FishingSpotTable.NAME,
                        FishingSpotTable.Columns.LOCATION_ID + " = ?", new String[]{getIdAsString()}
                ),
                new QueryHelper.UserDefineQueryInterface() {
                    @Override
                    public UserDefineObject getObject(UserDefineCursor cursor) {
                        return new FishingSpotCursor(cursor).getFishingSpot();
                    }
                }
        );
    }

    /**
     * Resets the location's fishing spots by first removing the old ones, then adding the new ones.
     * @param newFishingSpots The new collection of {@link FishingSpot} objects.
     */
    public void setFishingSpots(ArrayList<UserDefineObject> newFishingSpots) {
        ArrayList<UserDefineObject> oldFishingSpots = getFishingSpots();

        for (UserDefineObject oldSpot : oldFishingSpots)
            removeFishingSpot(oldSpot.getId());

        for (UserDefineObject newSpot : newFishingSpots)
            addFishingSpot((FishingSpot)newSpot);
    }

    public boolean addFishingSpot(FishingSpot fishingSpot) {
        fishingSpot.setLocationId(getId());
        return QueryHelper.insertQuery(FishingSpotTable.NAME, fishingSpot.getContentValues(getId()));
    }

    public boolean removeFishingSpot(UUID id) {
        return QueryHelper.deleteUserDefine(FishingSpotTable.NAME, id);
    }

    public boolean removeAllFishingSpots() {
        ArrayList<UserDefineObject> fishingSpots = getFishingSpots();
        for (UserDefineObject spot : fishingSpots)
            if (!removeFishingSpot(spot.getId()))
                return false;

        return true;
    }

    public int getFishingSpotCount() {
        return QueryHelper.queryCount(FishingSpotTable.NAME, FishingSpotTable.Columns.LOCATION_ID + " = ?", new String[]{ getIdAsString() });
    }
    //endregion

    public ArrayList<UserDefineObject> getCatches() {
        ArrayList<UserDefineObject> catches = new ArrayList<>();
        ArrayList<UserDefineObject> spots = getFishingSpots();

        for (UserDefineObject obj : spots) {
            FishingSpot spot = (FishingSpot)obj;
            catches.addAll(spot.getCatches());
        }

        return catches;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public int getFishCaughtCount() {
        return QueryHelper.queryLocationCatchCount(this);
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public Intent getShareIntent(Context context) {
        Intent intent =  super.getShareIntent(context);

        String text = getDisplayName() + " has " + getFishingSpotCount() + " fishing spots and " + getFishCaughtCount() + " fish caught. ";
        intent.putExtra(Intent.EXTRA_TEXT, text + intent.getStringExtra(Intent.EXTRA_TEXT));

        return intent;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public JSONObject toJson() throws JSONException {
        JSONObject json = super.toJson();
        json.put(Json.FISHING_SPOTS, JsonExporter.getJsonArray(getFishingSpots()));
        return json;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public String toKeywordsString(Context context) {
        return super.toKeywordsString(context) + UserDefineArrays.keywordsAsString(context, getFishingSpots());
    }
}

